from pathlib import Path
p=Path(__file__).parent
s=(p/'ui.html').read_text().replace('Ecossistema 02 | Flora','Ecossistema 03 | Insetos').replace('laboratório de biodiversidade vegetal','laboratório de fauna e flora interdependentes').replace('Flora.create()','Insects.create()').replace('Flora.tick(state)','Insects.tick(state)').replace('Flora.edit(state,sel,','Insects.edit(state,sel,').replace('ivEco031','ivEco032').replace('state.pollinators','state.insectMode').replace('Presentes (modelo)','Presentes (agentes)').replace('Polinizadores</label>','Fauna experimental</label>').replace('Ausentes</option>','Sem insetos</option>').replace('Sem mariposa da orquídea','Sem mariposas').replace('Coortes vegetais por célula, bancos de propágulos e polinização probabilística. Sem animais individuais, patógenos, salinidade ou arte final.','Coortes vegetais e agentes de insetos; símbolos diagnósticos, não sprites finais. Néctar de fundo e reservas iniciais de fezes são aproximações explícitas.').replace('1.120 células • seis espécies','1.120 células • seis plantas • quatro grupos de insetos').replace('<h2>Estado da bacia</h2>','<h2>Estado da bacia</h2><div id="insectStats" class="fine"></div><div id="insectPop" class="fine"></div><div class="row"><label><input id="showInsects" type="checkbox" checked> Mostrar insetos</label></div><hr>').replace('<button id="water">Irrigar</button>','<button id="water">Irrigar</button><button id="dung">Adicionar fezes</button><button id="wood">Adicionar madeira morta</button>').replace('let c=state.cells[sel];ctx.strokeStyle',"if($('showInsects').checked){for(let a of state.insects){let t=state.cells[a.pos],x=t.x*k+3+(a.id%3)*2,y=t.y*k+3+(a.id%4);ctx.fillStyle='#14251b';ctx.fillRect(x-1,y-1,5,5);ctx.fillStyle=Insects.P[a.sp].color;ctx.fillRect(x,y,3,3);}}let c=state.cells[sel];ctx.strokeStyle").replace("let fm=Flora.metrics(state)","let im=Insects.metrics(state),ie=state.insectEvents;$('insectStats').textContent=`${im.total} agentes • ${im.juveniles} juvenis • ${ie.births} nascimentos • ${ie.deaths} mortes • ${ie.pollinations} polinizações por visita`;$('insectPop').innerHTML=Insects.P.map((p,i)=>`<div><i class='dot' style='background:${p.color}'></i>${p.name}: <b>${im.count[i]}</b> · refeições: ${ie.meals[i]}</div>`).join('');$('inspect').innerHTML+=`<hr>Néctar: ${num(c.nectar)} · fezes: ${num(c.dung)} · madeira morta: ${num(c.wood)}<br>Agentes locais: ${state.insects.filter(a=>a.pos===sel).map(a=>Insects.P[a.sp].name+' ('+a.state+')').join(', ')||'nenhum'}`;let fm=Flora.metrics(state)").replace("for(let id of ['cut','compost','water','seed'])","for(let id of ['cut','compost','water','seed','dung','wood'])").replace("window.lab={", "$('showInsects').onchange=draw;for(let id of ['dung','wood'])$(id).onclick=()=>{if(!busy&&Insects.edit(state,sel,id)){$('log').textContent='Recurso orgânico externo adicionado e contabilizado.';update()}};window.lab={")
s=s.replace('/*ENGINE*/','\n'.join((p/f).read_text() for f in ['ecology.js','flora.js','insects.js']))
(p/'Ilha_Viva_Ecossistema_03.html').write_text(s)
